shader.vertex:
attribute vec3 Position;
attribute vec4 Color;
attribute vec2 TexCoord;
attribute vec4 RenderData;
attribute float Scale;

attribute float Time;

varying vec4 Color0;
varying vec2 TexCoord0;
varying vec4 RenderDataOut;
varying float ScaleOut;
varying float TimeOut;
uniform mat4 Transform;
void main(void)
{
    RenderDataOut = RenderData;
    ScaleOut = Scale;           // Passing data to fragment shader
    TimeOut = Time;             // Passing data to fragment shader
    Color0 = Color;
    TexCoord0 = TexCoord;
    gl_Position = Transform * vec4(Position.xyz, 1.0);
}

shader.fragment:
varying lowp vec4 Color0;
varying mediump vec2 TexCoord0;
varying lowp vec4 RenderDataOut;
varying lowp float ScaleOut;
varying lowp float TimeOut;
uniform sampler2D Texture0;
void main(void)
{
    vec4 Color = Color0 * texture2D(Texture0, TexCoord0);

    if(TimeOut > 0.0)
    {
        float scale = 1.0-(TimeOut/30.0);
        if(scale > 1.0) {
            scale = 1.0;
        }

        if(TimeOut > 32.0){
            scale = (TimeOut-32.0)/3.0;
        }

        Color.r *= scale;
        Color.g *= scale;
        Color.b *= scale;                    
    }

    gl_FragColor = Color;
}

shader.vertex:
attribute vec3 Position;
attribute vec4 Color;
attribute vec2 TexCoord;
attribute vec4 RenderData;

attribute float Time;
attribute float Intensity;

varying vec4 Color0;
varying vec2 TexCoord0;
varying vec4 RenderDataOut;

varying float TimeOut;
varying float IntensityOut;

uniform mat4 Transform;
void main(void)
{
    RenderDataOut = RenderData;
    TimeOut = Time;             // Passing data to fragment shader
    IntensityOut = Intensity;             // Passing data to fragment shader
    Color0 = Color;
    TexCoord0 = TexCoord;
    gl_Position = Transform * vec4(Position.xyz, 1.0);
}

shader.fragment:
varying lowp vec4 Color0;
varying mediump vec2 TexCoord0;
varying lowp vec4 RenderDataOut;

varying lowp float TimeOut;
varying lowp float IntensityOut;

uniform sampler2D Texture0;
void main(void)
{
    vec4 Color = Color0 * texture2D(Texture0, TexCoord0);

    if(TimeOut > 0.0)
    {
        float PosOff = TexCoord0.x*(100.0+cos(TimeOut*0.075)*50.0)+TexCoord0.y*(100.0+sin(TimeOut*0.05)*50.0);
        Color.r *= 1.0 - abs(sin((TimeOut+60.0+PosOff)/(180.0/3.14)*5.0))*0.3*IntensityOut*(Color.r*0.6+0.4);
        Color.g *= 1.0 - abs(sin((TimeOut+120.0+PosOff)/(180.0/3.14)*5.0))*0.3*IntensityOut*(Color.g*0.6+0.4);
        Color.b *= 1.0 - abs(sin((TimeOut+180.0+PosOff)/(180.0/3.14)*5.0))*0.3*IntensityOut*(Color.b*0.6+0.4);
    }

    gl_FragColor = Color;
}

shader.vertex:
attribute vec3 Position;
attribute vec4 Color;
attribute vec2 TexCoord;
attribute vec4 RenderData;

attribute float Time;

varying vec4 Color0;
varying vec2 TexCoord0;
varying vec4 RenderDataOut;

varying float TimeOut;
varying float IntensityOut;

uniform mat4 Transform;
void main(void)
{
    RenderDataOut = RenderData;
    TimeOut = Time;             // Passing data to fragment shader
    Color0 = Color;
    TexCoord0 = TexCoord;
    gl_Position = Transform * vec4(Position.xyz, 1.0);
}

shader.fragment:
varying lowp vec4 Color0;
varying mediump vec2 TexCoord0;
varying lowp vec4 RenderDataOut;

varying lowp float TimeOut;

uniform sampler2D Texture0;
void main(void)
{
    vec4 Color = Color0 * texture2D(Texture0, TexCoord0);

    if(TimeOut > 0.0)
    {
        Color.r *= 1.0+(TimeOut / 40.0)*1.0;
        Color.g -= (TimeOut / 40.0)*0.8;
        Color.b -= (TimeOut / 40.0)*0.8;                    
    }

    gl_FragColor = Color;
}

shader.vertex:
attribute vec3 Position;
attribute vec4 Color;
attribute vec2 TexCoord;
attribute vec4 RenderData;

attribute float Intensity;

varying vec4 Color0;
varying vec2 TexCoord0;
varying vec4 RenderDataOut;
varying float ScaleOut;

varying float IntensityOut;

uniform mat4 Transform;
void main(void)
{
    RenderDataOut = RenderData;
    IntensityOut = Intensity;             // Passing data to fragment shader
    Color0 = Color;
    TexCoord0 = TexCoord;
    gl_Position = Transform * vec4(Position.xyz, 1.0);
}

shader.fragment:
varying lowp vec4 Color0;
varying mediump vec2 TexCoord0;
varying lowp vec4 RenderDataOut;

varying lowp float IntensityOut;

uniform sampler2D Texture0;
void main(void)
{
    vec4 Color = Color0 * texture2D(Texture0, TexCoord0);

    Color *= IntensityOut;

    gl_FragColor = Color;
}

shader.vertex:
attribute vec3 Position;
attribute vec4 Color;
attribute vec2 TexCoord;
attribute vec4 RenderData;

attribute float Time;
attribute float Intensity;
attribute float Style;

varying vec4 Color0;
varying vec2 TexCoord0;
varying vec4 RenderDataOut;

varying float TimeOut;
varying float IntensityOut;
varying float StyleOut;

uniform mat4 Transform;
void main(void)
{
    RenderDataOut = RenderData;
    TimeOut = Time;             // Passing data to fragment shader
    IntensityOut = Intensity;             // Passing data to fragment shader
    StyleOut = Style;
    Color0 = Color;

    vec2 center = vec2(RenderData.x / 2.0, RenderData.y / 2.0);
    vec2 coord = TexCoord;
    float xScale = 1.0 + cos(Position.y+Time/34.0) * 0.1;
    float xOff = sin(Position.x * 0.1 * Intensity + Time / 20.0 * xScale * TexCoord.x * Intensity) * 0.01*Intensity - 0.01;

    if(Style == 1)
    {
        coord.x += xOff - xOff / 2.0;
        coord.y += 0;
    }

    TexCoord0 = coord;
    gl_Position = Transform * vec4(Position.xyz, 1.0);
}

shader.fragment:
varying lowp vec4 Color0;
varying mediump vec2 TexCoord0;
varying lowp vec4 RenderDataOut;

varying lowp float TimeOut;
varying lowp float IntensityOut;
varying lowp float StyleOut;

uniform sampler2D Texture0;
void main(void)
{
    vec4 Color = Color0 * texture2D(Texture0, TexCoord0);

    if(IntensityOut > 0.0 && StyleOut < 3)
    {
        float avg = (Color.r + Color.g + Color.b) / 3.0;

        if(avg > 0.75 + (1 - IntensityOut) * 0.25)
        {
            Color.r = 1.0;
            Color.g = 1.0;
            Color.b = 1.0;
        }
        else if(avg > 0.25 - (1 - IntensityOut) * 0.25)
        {
            Color.r = Color.r + IntensityOut * IntensityOut * IntensityOut;

            if(Color.r > 1.0)
            {
                Color.r = 1.0;
            }

            Color.g = Color.g - IntensityOut * (0.9+cos(TexCoord0.x * 5.0+TimeOut/15.0)*0.5);
            Color.b = Color.b - IntensityOut * (0.9+sin(TexCoord0.y * 12.0+TimeOut/23.0)*0.5);
        }
        else if(avg > 0.2 - (1 - IntensityOut) * 0.2)
        {
            Color.r = 0.2;
            Color.g = 0.0;
            Color.b = 0.0;
        }
        else
        {
            Color.r = 0.0;
            Color.g = 0.0;
            Color.b = 0.0;
        }
    }

    gl_FragColor = Color;
}
